-- Matriz schema, version 1: the whole data model of docs/database.md (v0.3), with the
-- constraints of ADR-007 decision 8. Applied by Flyway. Never edit this file once it has been
-- applied; change the schema with a new migration.
--
-- Identifiers are UUIDs generated by the application. Enumerations are text with a CHECK on
-- the API codes. Text is only required to be nonempty; maximum lengths come in I3 (OQ-003,
-- OQ-024). Foreign keys follow the module dependencies only, and nothing cascades.
-- Dates and times are timestamptz, an instant like the API's date-time [Proposal].

-- Identity --------------------------------------------------------------------------------

CREATE TABLE person (
    person_id     uuid NOT NULL,
    login_name    text NOT NULL,
    display_name  text NOT NULL,
    password_hash text NOT NULL,
    CONSTRAINT person_pk PRIMARY KEY (person_id),
    CONSTRAINT person_login_name_uk UNIQUE (login_name),
    CONSTRAINT person_login_name_nonempty_ck CHECK (login_name <> ''),
    CONSTRAINT person_display_name_nonempty_ck CHECK (display_name <> ''),
    CONSTRAINT person_password_hash_nonempty_ck CHECK (password_hash <> '')
);

-- Projects --------------------------------------------------------------------------------

CREATE TABLE project (
    project_id uuid NOT NULL,
    name       text NOT NULL,
    state      text NOT NULL DEFAULT 'ACTIVE',
    deleted_at timestamptz,
    CONSTRAINT project_pk PRIMARY KEY (project_id),
    CONSTRAINT project_name_nonempty_ck CHECK (name <> ''),
    CONSTRAINT project_state_ck CHECK (state IN ('ACTIVE', 'COMPLETED'))
);

CREATE TABLE membership (
    project_id uuid NOT NULL,
    person_id  uuid NOT NULL,
    role       text NOT NULL,
    CONSTRAINT membership_pk PRIMARY KEY (project_id, person_id),
    CONSTRAINT membership_project_fk FOREIGN KEY (project_id) REFERENCES project (project_id),
    CONSTRAINT membership_person_fk FOREIGN KEY (person_id) REFERENCES person (person_id),
    CONSTRAINT membership_role_ck CHECK (role IN ('PROJECT_OWNER', 'PROJECT_PARTICIPANT'))
);

-- Rule 1: at most one Project Owner per project. "At least one" is left to the application.
CREATE UNIQUE INDEX membership_one_owner_ux ON membership (project_id) WHERE role = 'PROJECT_OWNER';

-- Tasks -----------------------------------------------------------------------------------

CREATE TABLE task (
    task_id        uuid NOT NULL,
    project_id     uuid NOT NULL,
    title          text NOT NULL,
    state          text NOT NULL DEFAULT 'TO_DO',
    priority       text NOT NULL DEFAULT 'MEDIUM',
    deleted_at     timestamptz,
    -- Technical: the order in which tasks were created, for the oldest-first task list. Never
    -- exposed by the API (ADR-007 decision 8).
    creation_order bigint GENERATED ALWAYS AS IDENTITY,
    CONSTRAINT task_pk PRIMARY KEY (task_id),
    -- Referenced by assignment_task_fk (rule 8).
    CONSTRAINT task_project_uk UNIQUE (task_id, project_id),
    CONSTRAINT task_project_fk FOREIGN KEY (project_id) REFERENCES project (project_id),
    CONSTRAINT task_title_nonempty_ck CHECK (title <> ''),
    CONSTRAINT task_state_ck CHECK (state IN ('TO_DO', 'IN_PROGRESS', 'DONE')),
    CONSTRAINT task_priority_ck CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH'))
);

CREATE TABLE assignment (
    task_id    uuid NOT NULL,
    person_id  uuid NOT NULL,
    project_id uuid NOT NULL,
    CONSTRAINT assignment_pk PRIMARY KEY (task_id, person_id),
    -- Rule 8: the assignment's project is its task's project...
    CONSTRAINT assignment_task_fk FOREIGN KEY (task_id, project_id) REFERENCES task (task_id, project_id),
    -- ...and the assignee is a member of that project. Rule 2: a Membership that an Assignment
    -- references cannot be deleted.
    CONSTRAINT assignment_membership_fk FOREIGN KEY (project_id, person_id)
        REFERENCES membership (project_id, person_id) ON DELETE RESTRICT
);

CREATE TABLE comment (
    comment_id       uuid NOT NULL,
    task_id          uuid NOT NULL,
    author_person_id uuid NOT NULL,
    text             text NOT NULL,
    created_at       timestamptz NOT NULL,
    CONSTRAINT comment_pk PRIMARY KEY (comment_id),
    CONSTRAINT comment_task_fk FOREIGN KEY (task_id) REFERENCES task (task_id),
    -- Tasks depends on Identity for the author (ADR-007 decision 9).
    CONSTRAINT comment_author_fk FOREIGN KEY (author_person_id) REFERENCES person (person_id),
    CONSTRAINT comment_text_nonempty_ck CHECK (text <> '')
);
